  Widget _cornerText(String text) {
    return Text(
      text,
      style: GoogleFonts.jetBrainsMono(
        color: Colors.white,
        fontSize: 10,
        fontWeight: FontWeight.w900,
      ),
    );
  }
}

class _BillStripePainter extends CustomPainter {
  final Color stripeColor;
  _BillStripePainter(this.stripeColor);

